def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    tiles = []

    # Find each separated framed tile. The most common color in a tile
    # is its border; the remaining cells identify its interior color.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue

            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] != 0 and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        q.append((ny, nx))

            border = Counter(grid[y][x] for y, x in cells).most_common(1)[0][0]
            interior = [(y, x) for y, x in cells if grid[y][x] != border]
            if not interior:
                continue

            color = Counter(grid[y][x] for y, x in interior).most_common(1)[0][0]
            ys = [y for y, x in interior]
            xs = [x for y, x in interior]
            tiles.append((color, min(ys), max(ys), min(xs), max(xs)))

    if not tiles:
        return [row[:] for row in grid]

    ordinary = Counter(t[0] for t in tiles).most_common(1)[0][0]
    out = [row[:] for row in grid]

    horizontal = defaultdict(list)
    vertical = defaultdict(list)
    for color, r0, r1, c0, c1 in tiles:
        if color == ordinary:
            continue
        horizontal[(color, r0, r1)].append((c0, c1))
        vertical[(color, c0, c1)].append((r0, r1))

    for (color, r0, r1), spans in horizontal.items():
        spans.sort()
        for (_, left_end), (right_start, _) in zip(spans, spans[1:]):
            for r in range(r0, r1 + 1):
                for c in range(left_end + 1, right_start):
                    if out[r][c] == 0:
                        out[r][c] = color

    for (color, c0, c1), spans in vertical.items():
        spans.sort()
        for (_, top_end), (bottom_start, _) in zip(spans, spans[1:]):
            for r in range(top_end + 1, bottom_start):
                for c in range(c0, c1 + 1):
                    if out[r][c] == 0:
                        out[r][c] = color

    return out
